def upgrade() -> None:
    conn = op.get_bind()
    for r in RECIPES:
        row = conn.execute(
            sa.text("SELECT id, artist_id, prompt_id FROM tracks "
                    "WHERE legacy_id = :lid"),
            {"lid": r["legacy_id"]},
        ).fetchone()
        if row is None:
            continue
        track_id, artist_id, existing_prompt = row[0], row[1], row[2]
        if existing_prompt is not None:
            conn.execute(
                sa.text("UPDATE tracks SET tags = :t, platform = 'suno' "
                        "WHERE id = :id"),
                {"t": r["moods"], "id": track_id},
            )
            continue
        pid = str(uuid.uuid4())
        conn.execute(
            sa.text(
                "INSERT INTO prompts (id, artist_id, title, prompt_text, "
                "lyrics, price_credits, prompt_platform, prompt_weirdness, "
                "prompt_style_influence, prompt_model_version, is_published, "
                "is_deleted, pack_eligible, created_at, updated_at) VALUES "
                "(:id, :aid, :title, :ptext, :lyrics, :price, 'suno', :weird, "
                ":style, :model, :pub, false, true, now(), now())"
            ),
            {
                "id": pid, "aid": artist_id, "title": r["title"],
                "ptext": r["prompt_text"], "lyrics": r["lyrics"],
                "price": r["price"], "weird": r["weirdness"],
                "style": r["style_influence"], "model": r["model"],
                "pub": bool(r["published"]),
            },
        )
        conn.execute(
            sa.text("UPDATE tracks SET tags = :t, platform = 'suno', "
                    "prompt_id = :pid WHERE id = :id"),
            {"t": r["moods"], "pid": pid, "id": track_id},
        )


